//! Packets for the Play connection state in Minecraft 1.8.9 Protocol 47.

use crate::error::Result;
use crate::frame::RawPacket;
use crate::types::position::{read_position, read_string, Position};
use crate::types::varint::{read_varint, write_varint};
use bytes::{Buf, BufMut, Bytes, BytesMut};

/// Server -> Client Keep Alive packet (ID 0x00 in Play state).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ServerKeepAlivePacket {
    /// Keep alive ID generated by the server.
    pub id: i32,
}

impl ServerKeepAlivePacket {
    /// Creates a new `ServerKeepAlivePacket`.
    pub const fn new(id: i32) -> Self {
        Self { id }
    }

    /// Deserializes from raw payload bytes.
    pub fn from_payload(mut payload: Bytes) -> Result<Self> {
        let id = read_varint(&mut payload)?;
        Ok(Self { id })
    }
}

/// Client -> Server Keep Alive response packet (ID 0x00 in Play state).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ClientKeepAlivePacket {
    /// Matching keep alive ID sent back to the server.
    pub id: i32,
}

impl ClientKeepAlivePacket {
    /// Creates a response packet.
    pub const fn new(id: i32) -> Self {
        Self { id }
    }

    /// Serializes this packet into a `RawPacket`.
    pub fn to_raw_packet(&self) -> RawPacket {
        let mut payload = BytesMut::new();
        write_varint(&mut payload, self.id);
        RawPacket::new(0x00, payload.freeze())
    }
}

/// Server -> Client Join Game packet (ID 0x01 in Play state).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JoinGamePacket {
    /// Entity ID assigned to the player on the server.
    pub entity_id: i32,
    /// Gamemode: 0: Survival, 1: Creative, 2: Adventure, 3: Spectator. Bit 3 indicates hardcore.
    pub gamemode: u8,
    /// Dimension: -1: Nether, 0: Overworld, 1: End.
    pub dimension: i8,
    /// Difficulty: 0: Peaceful, 1: Easy, 2: Normal, 3: Hard.
    pub difficulty: u8,
    /// Maximum players allowed on server.
    pub max_players: u8,
    /// Level type: "default", "flat", "largeBiomes", "amplified", "customized".
    pub level_type: String,
    /// Whether reduced debug info is enabled.
    pub reduced_debug_info: bool,
}

impl JoinGamePacket {
    /// Deserializes from raw payload bytes.
    pub fn from_payload(mut payload: Bytes) -> Result<Self> {
        let entity_id = payload.get_i32();
        let gamemode = payload.get_u8();
        let dimension = payload.get_i8();
        let difficulty = payload.get_u8();
        let max_players = payload.get_u8();
        let level_type = read_string(&mut payload, 16)?;
        let reduced_debug_info = payload.get_u8() != 0;

        Ok(Self {
            entity_id,
            gamemode,
            dimension,
            difficulty,
            max_players,
            level_type,
            reduced_debug_info,
        })
    }
}

/// Server -> Client Spawn Position packet (ID 0x05 in Play state).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SpawnPositionPacket {
    /// World spawn coordinates.
    pub location: Position,
}

impl SpawnPositionPacket {
    /// Deserializes from raw payload bytes.
    pub fn from_payload(mut payload: Bytes) -> Result<Self> {
        let location = read_position(&mut payload)?;
        Ok(Self { location })
    }
}

/// Server -> Client Player Position And Look packet (ID 0x08 in Play state).
#[derive(Debug, Clone, PartialEq)]
pub struct PlayerPositionAndLookPacket {
    /// Absolute or relative X position.
    pub x: f64,
    /// Absolute or relative Y position (feet level).
    pub y: f64,
    /// Absolute or relative Z position.
    pub z: f64,
    /// Yaw angle in degrees.
    pub yaw: f32,
    /// Pitch angle in degrees.
    pub pitch: f32,
    /// Flags indicating relative coordinates bitfield (0x01: X, 0x02: Y, 0x04: Z, 0x08: Y_ROT, 0x10: X_ROT).
    pub flags: u8,
}

impl PlayerPositionAndLookPacket {
    /// Deserializes from raw payload bytes.
    pub fn from_payload(mut payload: Bytes) -> Result<Self> {
        let x = payload.get_f64();
        let y = payload.get_f64();
        let z = payload.get_f64();
        let yaw = payload.get_f32();
        let pitch = payload.get_f32();
        let flags = payload.get_u8();

        Ok(Self {
            x,
            y,
            z,
            yaw,
            pitch,
            flags,
        })
    }
}

/// Client -> Server Player Position And Look packet (ID 0x06 in Play state).
#[derive(Debug, Clone, PartialEq)]
pub struct ClientPlayerPositionAndLookPacket {
    /// Absolute X position.
    pub x: f64,
    /// Absolute Y position (feet level).
    pub feet_y: f64,
    /// Absolute Z position.
    pub z: f64,
    /// Yaw angle in degrees.
    pub yaw: f32,
    /// Pitch angle in degrees.
    pub pitch: f32,
    /// True if the client is on the ground.
    pub on_ground: bool,
}

impl ClientPlayerPositionAndLookPacket {
    /// Creates a new position report.
    pub fn new(x: f64, feet_y: f64, z: f64, yaw: f32, pitch: f32, on_ground: bool) -> Self {
        Self {
            x,
            feet_y,
            z,
            yaw,
            pitch,
            on_ground,
        }
    }

    /// Serializes this packet into a `RawPacket`.
    pub fn to_raw_packet(&self) -> RawPacket {
        let mut payload = BytesMut::with_capacity(33);
        payload.extend_from_slice(&self.x.to_be_bytes());
        payload.extend_from_slice(&self.feet_y.to_be_bytes());
        payload.extend_from_slice(&self.z.to_be_bytes());
        payload.extend_from_slice(&self.yaw.to_be_bytes());
        payload.extend_from_slice(&self.pitch.to_be_bytes());
        payload.put_u8(if self.on_ground { 1 } else { 0 });

        RawPacket::new(0x06, payload.freeze())
    }
}

/// Server -> Client Chat Message packet (ID 0x02 in Play state).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ServerChatMessagePacket {
    /// JSON chat data string.
    pub message_json: String,
    /// Chat position: 0: Chat box, 1: System message, 2: Above action bar.
    pub position: u8,
}

impl ServerChatMessagePacket {
    /// Deserializes from raw payload bytes.
    pub fn from_payload(mut payload: Bytes) -> Result<Self> {
        let message_json = read_string(&mut payload, 32767)?;
        let position = if payload.has_remaining() {
            payload.get_u8()
        } else {
            0
        };

        Ok(Self {
            message_json,
            position,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn keep_alive_packet_roundtrip() {
        let server_ka = ServerKeepAlivePacket::new(1234567);
        let client_ka = ClientKeepAlivePacket::new(server_ka.id);
        let raw = client_ka.to_raw_packet();

        assert_eq!(raw.id, 0x00);
        let mut payload = raw.payload;
        let decoded_id = read_varint(&mut payload).unwrap();
        assert_eq!(decoded_id, 1234567);
    }

    #[test]
    fn client_position_and_look_serialization() {
        let pos_look = ClientPlayerPositionAndLookPacket::new(12.5, 64.0, -45.75, 90.0, 0.0, true);
        let raw = pos_look.to_raw_packet();
        assert_eq!(raw.id, 0x06);
        assert_eq!(raw.payload.len(), 33);
    }

    #[test]
    fn player_position_and_look_decode() {
        let mut buf = BytesMut::new();
        buf.extend_from_slice(&100.5f64.to_be_bytes());
        buf.extend_from_slice(&65.0f64.to_be_bytes());
        buf.extend_from_slice(&(-200.25f64).to_be_bytes());
        buf.extend_from_slice(&180.0f32.to_be_bytes());
        buf.extend_from_slice(&(-15.0f32).to_be_bytes());
        buf.put_u8(0); // absolute coordinates

        let decoded = PlayerPositionAndLookPacket::from_payload(buf.freeze()).unwrap();
        assert_eq!(decoded.x, 100.5);
        assert_eq!(decoded.y, 65.0);
        assert_eq!(decoded.z, -200.25);
        assert_eq!(decoded.yaw, 180.0);
        assert_eq!(decoded.pitch, -15.0);
        assert_eq!(decoded.flags, 0);
    }
}
